// ── Helpers ─────────────────────────────────────────────────────────────

/// Fully-qualified worker identity (`{adapter}-{worker_id}`).
///
/// Used as the claim actor, registry key, and strand identity to prevent
/// collisions when workers from different adapter pools share a NATO name.
fn qualified_id(&self) -> String {
    format!("{}-{}", self.config.agent.default, self.worker_name)
}

/// Release the current bead (if any) with proper telemetry and error handling.
///
/// This is a best-effort operation used during graceful shutdown to reduce
/// orphaned beads. If the release fails, we log the error but continue stopping
/// — a release failure should not block shutdown.
async fn release_current_bead(&mut self, reason: &str) {
    if let Some(ref bead) = self.current_bead {
        let bead_id = bead.id.clone();
        tracing::info!(bead_id = %bead_id, reason, "releasing bead on shutdown");

        // Emit bead released event for telemetry visibility.
        let _ = self
            .telemetry
            .emit(EventKind::BeadReleased {
                bead_id: bead_id.clone(),
                reason: reason.to_string(),
            });

        // Best-effort release with timeout to prevent blocking shutdown.
        match tokio::time::timeout(
            std::time::Duration::from_secs(30),
            self.store.release(&bead_id),
        )
        .await
        {
            Ok(Ok(())) => {
                tracing::debug!(bead_id = %bead_id, "successfully released bead on shutdown");
            }
            Ok(Err(e)) => {
                tracing::warn!(bead_id = %bead_id, error = %e, "failed to release bead on shutdown");
                let _ = self.telemetry.emit(EventKind::BeadReleaseFailed {
                    bead_id,
                    reason: format!("release failed: {}", e),
                });
            }
            Err(_) => {
                tracing::warn!(bead_id = %bead_id, "release timed out after 30s");
                let _ = self.telemetry.emit(EventKind::BeadReleaseFailed {
                    bead_id,
                    reason: "release timed out after 30s".to_string(),
                });
            }
        }

        // Clear the current bead to prevent double-release attempts.
        self.current_bead = None;
    }
}

